/**
 * Ready-made forms. Each template only lists fields; keys are generated by the server
 * (except "email", which links the entry to the customer).
 */
import { __ } from '@wordpress/i18n';

const opt = ( value, label ) => ( { value, label } );

const name = () => ( {
	type: 'name',
	label: __( 'Name', 'bookora' ),
	required: true,
	format: 'first_last',
} );
const email = ( width = 'half' ) => ( {
	type: 'email',
	key: 'email',
	label: __( 'Email', 'bookora' ),
	required: true,
	placeholder: 'name@example.com',
	width,
} );
const phone = ( required = false, width = 'half' ) => ( {
	type: 'phone',
	label: __( 'Phone', 'bookora' ),
	required,
	width,
} );
const message = ( label, required = false, rows = 3 ) => ( {
	type: 'textarea',
	label,
	required,
	rows,
} );
const service = ( label = __( 'Service', 'bookora' ) ) => ( {
	type: 'service',
	label,
	required: true,
} );
const appointment = () => ( {
	type: 'appointment',
	label: __( 'Choose a date and time', 'bookora' ),
	required: true,
} );
const consent = ( text ) => ( {
	type: 'consent',
	label: __( 'Privacy', 'bookora' ),
	required: true,
	text:
		text ||
		__(
			'I agree that my data will be processed to handle my request.',
			'bookora'
		),
} );
const yesNo = ( label ) => ( {
	type: 'radio',
	label,
	layout: 'inline',
	options: [
		opt( 'yes', __( 'Yes', 'bookora' ) ),
		opt( 'no', __( 'No', 'bookora' ) ),
	],
} );

